#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int height;
    int index;
} Rectangle;

static int parent[100000];
static int active[100000];

static int find_root(int x) {
    if (parent[x] != x)
        parent[x] = find_root(parent[x]);
    return parent[x];
}

static int unite(int a, int b) {
    int root_a = find_root(a);
    int root_b = find_root(b);
    if (root_a == root_b)
        return 0;
    parent[root_a] = root_b;
    return 1;
}

static int compare_rectangles(const void *a, const void *b) {
    const Rectangle *ra = (const Rectangle *)a;
    const Rectangle *rb = (const Rectangle *)b;
    if (ra->height < rb->height) return -1;
    if (ra->height > rb->height) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1)
        return 0;

    Rectangle rectangles[100000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &rectangles[i].height);
        rectangles[i].index = i;
        parent[i] = i;
    }

    qsort(rectangles, n, sizeof(Rectangle), compare_rectangles);

    int components = 0;
    int max_components = 0;

    for (int i = n - 1; i >= 0; ) {
        int j = i;
        while (j >= 0 && rectangles[j].height == rectangles[i].height)
            j--;

        for (int k = i; k > j; k--) {
            int index = rectangles[k].index;
            active[index] = 1;
            components++;
            if (index > 0 && active[index - 1])
                components -= unite(index, index - 1);
            if (index + 1 < n && active[index + 1])
                components -= unite(index, index + 1);
        }

        if (components > max_components)
            max_components = components;
        i = j;
    }

    printf("%d\n", max_components + 1);
    return 0;
}
